OPJ_BOOL write_j2k_sot_marker(opj_j2k_t* p_j2k, OPJ_BYTE* p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32* p_data_written, const opj_stream_private_t* p_stream, opj_event_mgr_t* p_manager) {
    (void)p_j2k;
    (void)p_stream;

    if (!p_data || !p_data_written || !p_manager) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Invalid arguments when writing SOT marker.\n");
        return OPJ_FALSE;
    }

    if (p_total_data_size < 10) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Insufficient buffer space to write SOT marker.\n");
        return OPJ_FALSE;
    }

    p_data[0] = (OPJ_BYTE)(0xFF);
    p_data[1] = (OPJ_BYTE)(0x90);  // SOT marker code

    p_data[2] = (OPJ_BYTE)(0x00);  // Length: bytes 3-4
    p_data[3] = (OPJ_BYTE)(0x08);  // Length = 8 bytes (from 0x0008)

    p_data[4] = (OPJ_BYTE)(0x00);  // Tile part index
    p_data[5] = (OPJ_BYTE)(0x00);

    p_data[6] = (OPJ_BYTE)(0x00);  // Tile index
    p_data[7] = (OPJ_BYTE)(0x00);

    p_data[8] = (OPJ_BYTE)(0x00);  // Number of resolution levels
    p_data[9] = (OPJ_BYTE)(0x01);

    *p_data_written = 10;

    return OPJ_TRUE;
}

OPJ_BOOL write_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    OPJ_UNUSED(p_stream);

    if (!p_j2k || !p_data || !p_data_written || !p_manager || !p_j2k->cstr_info || p_total_data_size < 8) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Invalid parameters when writing SOT marker.\n");
        return OPJ_FALSE;
    }

    if (*p_data_written + 8 > p_total_data_size) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Insufficient buffer space to write SOT marker.\n");
        return OPJ_FALSE;
    }

    p_data[(*p_data_written)++] = 0xFF;
    p_data[(*p_data_written)++] = 0x90; // SOT marker

    /* Length of SOT segment (2 bytes, fixed to 6 bytes for basic case) */
    p_data[(*p_data_written)++] = (OPJ_BYTE)(6 >> 8);
    p_data[(*p_data_written)++] = (OPJ_BYTE)(6 & 0x00FF);

    /* Tile index (2 bytes) */
    p_data[(*p_data_written)++] = (OPJ_BYTE)(p_j2k->current_tile_number >> 8);
    p_data[(*p_data_written)++] = (OPJ_BYTE)(p_j2k->current_tile_number & 0x00FF);

    /* Number of layers (2 bytes) */
    p_data[(*p_data_written)++] = (OPJ_BYTE)(p_j2k->cstr_info->numlayers >> 8);
    p_data[(*p_data_written)++] = (OPJ_BYTE)(p_j2k->cstr_info->numlayers & 0x00FF);

    return OPJ_TRUE;
}

OPJ_BOOL write_j2k_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size,
                              OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream,
                              opj_event_mgr_t *p_manager) {
    OPJ_UINT32 offset = 0;

    if (!p_j2k || !p_data || !p_data_written || !p_manager) {
        opj_event_msg(p_manager, EVT_ERROR, "Invalid arguments to write_j2k_sot_marker\n");
        return OPJ_FALSE;
    }

    if (p_total_data_size < 8) {
        opj_event_msg(p_manager, EVT_ERROR, "Insufficient buffer size for SOT marker\n");
        return OPJ_FALSE;
    }

    /* SOT marker code is 0xFF91 */
    p_data[offset++] = 0xFF;
    p_data[offset++] = 0x91;
    /* Length of SOT marker (excluding first two bytes) is 6 bytes */
    p_data[offset++] = 0x00;
    p_data[offset++] = 0x06;
    /* Tile index */
    p_data[offset++] = (OPJ_BYTE)((p_j2k->current_tile_num >> 8) & 0xFF);
    p_data[offset++] = (OPJ_BYTE)(p_j2k->current_tile_num & 0xFF);
    /* Length of tile data (placeholder 0x00000000 for now) */
    p_data[offset++] = 0x00;
    p_data[offset++] = 0x00;
    p_data[offset++] = 0x00;
    p_data[offset++] = 0x00;

    *p_data_written = 8;

    return OPJ_TRUE;
}

OPJ_BOOL write_j2k_sot_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    (void)p_stream;  // Mark as unused

    if (!p_j2k || !p_data || !p_data_written || !p_manager) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Invalid input pointers for SOT marker.\n");
        return OPJ_FALSE;
    }

    // SOT marker is 16 bytes long
    if (p_total_data_size < 16) {
        opj_event_msg(p_manager, OPJ_EVENT_MSG_ERROR, "Insufficient buffer space for SOT marker.\n");
        return OPJ_FALSE;
    }

    // Write the SOT marker
    p_data[0] = 0x52;  // 'R'
    p_data[1] = 0x49;  // 'I'
    p_data[2] = 0x46;  // 'F'
    p_data[3] = 0x46;  // 'F'
    p_data[4] = 0x00;  // Version
    p_data[5] = 0x00;
    p_data[6] = 0x00;
    p_data[7] = 0x00;
    p_data[8] = 0x00;
    p_data[9] = 0x00;
    p_data[10] = 0x00;
    p_data[11] = 0x00;
    p_data[12] = 0x00;
    p_data[13] = 0x00;
    p_data[14] = 0x00;
    p_data[15] = 0x00;

    *p_data_written = 16;
    return OPJ_TRUE;
}

OPJ_BOOL write_SOT_marker(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    if (!p_j2k || !p_data || !p_data_written || !p_manager) {
        OPJ_ERROR(p_manager, "Invalid arguments to write_SOT_marker");
        return OPJ_FALSE;
    }

    if (p_total_data_size < 10) {
        OPJ_ERROR(p_manager, "Insufficient buffer size to write SOT marker");
        return OPJ_FALSE;
    }

    OPJ_UINT32 written = 0;

    /* Write SOT marker (0xFF91) */
    p_data[written++] = 0xFF;
    p_data[written++] = 0x91;

    /* Length of SOT marker segment (8 bytes) */
    p_data[written++] = 0x00;
    p_data[written++] = 0x08;

    /* Write other SOT parameters (e.g., tile index, number of tiles, etc.) */
    /* These values are simplified for illustration and should be derived from p_j2k data */
    p_data[written++] = 0x00;
    p_data[written++] = 0x00;
    p_data[written++] = 0x00;
    p_data[written++] = 0x01;

    *p_data_written = written;

    return OPJ_TRUE;
}
